import hashlib,json,datetime
from pathlib import Path
out=Path('survey/out')
def sha(path):
 h=hashlib.sha256()
 with Path(path).open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
p=json.loads((out/'polarity-final-provenance.json').read_text());checks={}
files={'polarity-sessions.jsonl':p['original_partial_telemetry_equivalence']['original_sessions_sha256'],'polarity-telemetry-sessions.jsonl':p['original_full_execution']['sessions_sha256'],'polarity-sequential-sessions.jsonl':p['sequential_correction_execution']['sessions_sha256'],'polarity-final-sessions.jsonl':p['sessions_sha256'],'polarity-telemetry-findings.json':p['original_report_export']['findings_sha256'],'polarity-telemetry-findings.md':p['original_report_export']['findings_markdown_sha256'],'polarity-telemetry-stock-diagnostics.json':p['original_report_export']['stock_diagnostics_sha256'],'polarity-final-findings.json':p['findings_sha256'],'polarity-final-findings.md':p['findings_markdown_sha256'],'polarity-final-stock-diagnostics.json':p['stock_diagnostics_sha256'],'polarity-telemetry-frozen-release-binary':p['original_full_execution']['executable_sha256'],'polarity-sequential-frozen-release-binary':p['sequential_correction_execution']['executable_sha256']}
for name,expected in files.items():
 actual=sha(out/name);assert actual==expected,(name,actual,expected);checks[str(out/name)]=actual
# Revalidate original panic count and the exact retained 83 previously-valid sequential records.
assembly=p['assembly_receipt'];sequential={a['id'] for a in assembly['per_arm']};prior_valid={};panics=0
for line in (out/'polarity-telemetry-sessions.jsonl').open('rb'):
 r=json.loads(line)
 if r['arm'] in sequential:
  if r['outcome']['valid']:prior_valid[(r['arm'],r['seed'])]=r
  if r['outcome']['finish_reason']=='panic':panics+=1
assert len(prior_valid)==83 and panics==237
matching=0
for line in (out/'polarity-domestic-sessions.jsonl').open('rb'):
 r=json.loads(line);key=(r['arm'],r['seed'])
 if key in prior_valid:assert r==prior_valid[key];matching+=1
assert matching==83
result={'schema_version':1,'checked_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':'python3 survey/out/polarity-domestic-retained-audit.py','script_source':Path(__file__).read_text(),'original_raw_logs_and_reports_not_overwritten':True,'prior_artifact_sha256_checks':checks,'original_sequential_panics_retained':237,'previously_valid_sequential_records_identical_in_current_data':83,'previously_valid_sequential_missing':0,'previously_valid_sequential_mismatches':0,'original_partial_records_preserved':4272,'prior_amendment_receipts':{'telemetry':p['original_partial_telemetry_equivalence'],'sequential':p['assembly_receipt']}}
(out/'polarity-domestic-retained-audit.json').write_text(json.dumps(result,indent=2,sort_keys=True,allow_nan=False)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['script_source','prior_amendment_receipts']},indent=2))
